contract InvMutTest is Test {
    C c;
    address originalAdmin;

    function setUp() public {
        c = new C();
        originalAdmin = address(this);
    }

    function testFuzz_property(address x, address y) public {
        vm.assume(x != originalAdmin && y != originalAdmin);
        vm.assume(x != y);

        bool first = true;
        try c.setOwner(x) {
            first = true;
        } catch {
            first = false;
        }

        bool second = true;
        try c.setOwner(y) {
            second = true;
        } catch {
            second = false;
        }

        assertTrue(
            first && second && c.owner() == y,
            "original admin can reassign owner repeatedly; owner tracks last assignment"
        );
    }
}

