pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        address admin = address(this);

        // Rule: only the admin can change owner.
        if (actor == admin) {
            vm.prank(actor);
            bool ok;
            try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
            assertTrue(ok && c.owner() == newOwner);
        } else {
            vm.prank(actor);
            bool ok;
            try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
            assertTrue(!ok && c.owner() == admin,
                "non-admin must not be able to set owner");
        }
    }
}

